PAIRS = {")": "(", "]": "[", "}": "{"}


def balanced(s):
    """True if all (), [], {} in s are properly nested; other characters are ignored."""
    stack = []
    for c in s:
        if c in "([{":
            stack.append(c)
        elif c in PAIRS:
            if not stack or stack.pop() != PAIRS[c]:
                return False
    return not stack
