import heapq


class KthLargest:
    """Track the k-th largest value in a stream using a min-heap of the k largest values."""

    def __init__(self, k, nums=()):
        self.k = k
        self.heap = []
        for n in nums:
            self.add(n)

    def add(self, val):
        heapq.heappush(self.heap, val)
        if len(self.heap) > self.k:
            heapq.heappop(self.heap)

        if len(self.heap) < self.k:
            return None

        return self.heap[0]
