# file: trie.py
class Trie:
    def __init__(self):
        self.root = {"children": {}, "count": 0, "end": False}

    def insert(self, word):
        if self.contains(word):
            return False
        node = self.root
        for ch in word:
            node = node["children"].setdefault(ch, {"children": {}, "count": 0, "end": False})
            node["count"] += 1
        node["end"] = True
        return True

    def contains(self, word):
        node = self._walk(word)
        return node is not None and node["end"]

    def count_prefix(self, prefix):
        """Number of stored words starting with prefix."""
        node = self._walk(prefix)
        return node["count"] if node is not None else 0

    def delete(self, word):
        if not self.contains(word):
            return False

        node = self.root
        for ch in word:
            # We must decrement the count of every node in the path
            # but we skip the root's count as it doesn't represent a character
            child = node["children"][ch]
            child["count"] -= 1
            node = child

        node["end"] = False
        return True

    def _walk(self, s):
        node = self.root
        for ch in s:
            node = node["children"].get(ch)
            if node is None:
                return None
        return node
