def normalize(path):
    """Normalize an absolute POSIX path: collapse //, resolve . and .. ('..' at root stays at root). No trailing slash except root."""
    parts = []
    for p in path.split("/"):
        if p in ("", "."):
            continue
        if p == "..":
            if parts:
                parts.pop()
        else:
            parts.append(p)

    res = "/" + "/".join(parts)
    return res
