# file: solution.py
def caesar(text, shift):
    result = []
    # Normalize shift to be within 0-25
    shift = shift % 26

    for char in text:
        if 'a' <= char <= 'z':
            # Calculate new position for lowercase
            new_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            result.append(new_char)
        elif 'A' <= char <= 'Z':
            # Calculate new position for uppercase
            new_char = chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            result.append(new_char)
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)

    return "".join(result)
