def title_case(s):
    if not s:
        return ""

    small_words = {'a', 'an', 'the', 'of', 'in', 'on', 'and', 'or', 'to', 'for'}
    words = s.split(' ')
    result = []

    for i, word in enumerate(words):
        # Convert word to lowercase first to handle input like 'THE'
        lower_word = word.lower()

        # Check if it's the first word, the last word, or not in the small_words list
        if i == 0 or i == len(words) - 1 or lower_word not in small_words:
            result.append(lower_word.capitalize())
        else:
            result.append(lower_word)

    return ' '.join(result)
