def gcd_all(nums):
    if not nums:
        raise ValueError("List cannot be empty")

    def get_gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    result = nums[0]
    for i in range(1, len(nums)):
        result = get_gcd(result, nums[i])
    return result


def lcm_all(nums):
    if not nums:
        raise ValueError("List cannot be empty")

    def get_gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def get_lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // get_gcd(a, b)

    result = nums[0]
    for i in range(1, len(nums)):
        result = get_lcm(result, nums[i])
    return result
