def is_ipv4(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        # Check if part is empty or contains non-digits
        if not part or not part.isdigit():
            return False

        # Check for leading zeros: '0' is allowed, '01' is not
        if len(part) > 1 and part[0] == '0':
            return False

        # Check range 0-255
        if not (0 <= int(part) <= 255):
            return False

    return True
