def invert(d):
    inverted = {}
    # Track keys for each value to maintain insertion order
    value_to_keys = {}

    for k, v in d.items():
        if v not in value_to_keys:
            value_to_keys[v] = []
        value_to_keys[v].append(k)

    for v, keys in value_to_keys.items():
        if len(keys) == 1:
            inverted[v] = keys[0]
        else:
            inverted[v] = keys

    return inverted
