def parse_color(s):
    if not isinstance(s, str) or not s.startswith('#'):
        raise ValueError("Color must start with '#'")

    hex_digits = s[1:]

    if len(hex_digits) == 3:
        # Short form #rgb -> #rrggbb
        r_hex = hex_digits[0] * 2
        g_hex = hex_digits[1] * 2
        b_hex = hex_digits[2] * 2
    elif len(hex_digits) == 6:
        # Full form #rrggbb
        r_hex = hex_digits[0:2]
        g_hex = hex_digits[2:4]
        b_hex = hex_digits[4:6]
    else:
        raise ValueError("Invalid hex color length")

    try:
        r = int(r_hex, 16)
        g = int(g_hex, 16)
        b = int(b_hex, 16)
    except ValueError:
        raise ValueError("Invalid hex digits")

    return (r, g, b)
