def is_valid_board(board):
    # Check rows
    for row in board:
        seen = set()
        for char in row:
            if char != '.':
                if char in seen:
                    return False
                seen.add(char)

    # Check columns
    for col in range(9):
        seen = set()
        for row in range(9):
            char = board[row][col]
            if char != '.':
                if char in seen:
                    return False
                seen.add(char)

    # Check 3x3 boxes
    for box_row in range(0, 9, 3):
        for box_col in range(0, 9, 3):
            seen = set()
            for r in range(box_row, box_row + 3):
                for c in range(box_col, box_col + 3):
                    char = board[r][c]
                    if char != '.':
                        if char in seen:
                            return False
                        seen.add(char)

    return True
