def to_words(n):
    if not isinstance(n, int) or n < 0 or n > 999999:
        raise ValueError("n must be between 0 and 999999 inclusive")

    if n == 0:
        return "zero"

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def helper(num):
        res = []
        if num >= 100:
            res.append(units[num // 100] + " hundred")
            num %= 100

        if num >= 20:
            t = tens[num // 10]
            u = units[num % 10]
            if u:
                res.append(f"{t}-{u}")
            else:
                res.append(t)
        elif num >= 10:
            res.append(teens[num - 10])
        elif num > 0:
            res.append(units[num])

        return res

    parts = []

    # Thousands part
    thousands = n // 1000
    if thousands > 0:
        parts.extend(helper(thousands))
        parts.append("thousand")

    # Remainder part
    remainder = n % 1000
    if remainder > 0:
        # If remainder is >= 100, we need to handle the hundred part separately 
        # to avoid "one thousand one hundred" becoming "one thousand one hundred" 
        # (the helper handles the hundred logic)
