def count_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    # Convert to list of lists of ints for mutability and easier processing
    matrix = [list(map(int, list(row))) for row in grid]

    count = 0
    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 1:
                count += 1
                # Use iterative BFS to avoid recursion depth issues
                queue = [(r, c)]
                matrix[r][c] = 0  # Mark as visited

                while queue:
                    curr_r, curr_c = queue.pop(0)

                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc

                        if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] == 1:
                            matrix[nr][nc] = 0  # Mark as visited
                            queue.append((nr, nc))

    return count
