def is_bipartite(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        if u == v:
            return False
        adj[u].append(v)
        adj[v].append(u)

    colors = {}  # node -> color (0 or 1)

    for i in range(n):
        if i not in colors:
            # Start BFS/DFS for a new connected component
            stack = [(i, 0)]
            colors[i] = 0
            while stack:
                u, c = stack.pop()
                for v in adj[u]:
                    if v in colors:
                        if colors[v] == c:
                            return False
                    else:
                        colors[v] = 1 - c
                        stack.append((v, 1 - c))
    return True
