import re

def render(template, context):
    # Regex to find {{ ... }} blocks
    # We use a lookahead to check for unclosed {{
    pattern = re.compile(r'\{\{(.*?)\}\}')

    # Check for unclosed {{
    # A simple way is to count {{ and }}
    # But more robustly: find all {{ and check if they have a matching }}
    pos = 0
    while True:
        start = template.find('{{', pos)
        if start == -1:
            break
        end = template.find('}}', start)
        if end == -1:
            raise ValueError("Unclosed {{")
        pos = end + 2

    def get_value(path, default_val):
        parts = path.split('.')
        current = context
        try:
            for part in parts:
                if isinstance(current, dict):
                    current = current[part]
                else:
                    # Handle case where we try to dot into a non-dict
                    current = getattr(current, part)
            return str(current)
        except (KeyError, AttributeError):
            if default_val is not None:
                return default_val
            raise KeyError(f"Key '{path}' not found in context")

    def replace(match):
        content = match.group(1).strip()

        if '|' in content:
            name_part, default_part = content.split('|', 1)
            name = name_part.strip()
            default_val = default_part.strip()
            return get_value(name, default_val)
        else:
            name = content
            return get_value(name, None)

    return pattern.sub(replace, template)
