def to_rpn(tokens):
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    associativity = {'+': 'L', '-': 'L', '*': 'L', '/': 'L', '^': 'R'}

    output = []
    stack = []

    for token in tokens:
        if token in precedence:
            while stack and stack[-1] != '(':
                top = stack[-1]
                if (associativity[token] == 'L' and precedence[token] <= precedence[top]) or \
                   (associativity[token] == 'R' and precedence[token] < precedence[top]):
                    output.append(stack.pop())
                else:
                    break
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if not stack:
                raise ValueError("Mismatched parentheses")
            stack.pop()  # Pop '('
        else:
            # Operand
            output.append(token)

    while stack:
        if stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output.append(stack.pop())

    return output
