from collections import deque, defaultdict

def plan(tasks):
    if not tasks:
        return {}, []

    task_map = {t.name: t for t in tasks}
    adj = defaultdict(list)
    in_degree = {t.name: 0 for t in tasks}

    # Build graph and check for unknown dependencies
    for t in tasks:
        for dep_name in t.deps:
            if dep_name not in task_map:
                raise ValueError(f"Unknown dependency: {dep_name}")
            adj[dep_name].append(t.name)
            in_degree[t.name] += 1

    # Topological Sort (Kahn's Algorithm)
    queue = deque([name for name, degree in in_degree.items() if degree == 0])
    topo_order = []

    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topo_order) != len(tasks):
        raise ValueError("Cycle detected in task dependencies")

    # Calculate Schedule
    schedule = {}
    # To handle ties in critical path logic (smallest name), 
    # we process in topo order but need to track finish times.
    for name in topo_order:
        t = task_map[name]
        if not t.deps:
            start_time = 0
        else:
            start_time = max(schedule[dep][1] for dep in t.deps)
        schedule[name] = (start_time, start_time + t.duration)

    # Calculate Critical Path
    # 1. Find task with greatest finish (ties: smallest name)
    # 2. Step to dependency whose finish == current start (ties: smallest name)
    # 3. Return in execution order (start to finish)

    # Find end node
    max_finish = -1
    end_node = None
    for name, (start, finish) in schedule.items():
        if finish > max_finish:
            max_finish = finish
            end_node = name
        elif finish == max_finish:
            if end_node is None or name < end_node:
                end_node = name

    critical_path_rev = []
    curr = end_node
    while curr is not None:
        critical_path_rev.append(curr)
        t = task_map[curr]
        start_val = schedule[curr][0]

        # Find dependency whose finish == current start (ties: smallest name)
        next_node = None
        for dep_name in t.deps:
            if schedule[dep_name][1] == start_val:
                if next_node is None or dep_name < next_node:
                    next_node = dep_name
        curr = next_node

    return schedule, critical_path_rev[::-1]
