def mst(n, edges):
    if n <= 1:
        return (0, [])

    # Sort edges by (w, min(u,v), max(u,v))
    # We normalize edges to (min(u,v), max(u,v), w) for sorting and output
    normalized_edges = []
    for u, v, w in edges:
        if u == v:
            continue
        u_norm, v_norm = (u, v) if u < v else (v, u)
        normalized_edges.append((u_norm, v_norm, w))

    # Sort criteria: w, then min(u,v), then max(u,v)
    # The tuple (w, u_norm, v_norm) matches the requirement
    sorted_edges = sorted(normalized_edges, key=lambda x: (x[2], x[0], x[1]))

    parent = list(range(n))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    total_weight = 0
    chosen = []
    edges_count = 0

    for u, v, w in sorted_edges:
        if union(u, v):
            total_weight += w
            chosen.append((u, v, w))
            edges_count += 1
            if edges_count == n - 1:
                break

    if edges_count != n - 1:
        raise ValueError("Graph is not connected")

    return (total_weight, chosen)
