def shortest(n, edges, src):
    dist = [float('inf')] * n
    dist[src] = 0

    # Relax edges n-1 times
    for _ in range(n - 1):
        changed = False
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            break

    # Check for negative-weight cycles reachable from src
    for u, v, w in edges:
        if dist[u] != float('inf') and dist[u] + w < dist[v]:
            raise ValueError("Negative-weight cycle detected")

    return dist
