import math

class SegmentTree:
    def __init__(self, values, op='sum'):
        self.n = len(values)
        self.op = op

        if op == 'sum':
            self.identity = 0
            self.func = lambda a, b: a + b
        elif op == 'min':
            self.identity = float('inf')
            self.func = min
        elif op == 'max':
            self.identity = float('-inf')
            self.func = max
        else:
            raise ValueError(f"Unknown op: {op}")

        # Build a complete binary tree in a flat array
        # Size is 2 * next_power_of_2
        self.size = 1
        while self.size < self.n:
            self.size *= 2

        self.tree = [self.identity] * (2 * self.size)

        # Initialize leaves
        for i in range(self.n):
            self.tree[self.size + i] = values[i]

        # Build tree from bottom up
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = self.func(self.tree[2 * i], self.tree[2 * i + 1])

    def update(self, i, value):
        if not (0 <= i < self.n):
            raise IndexError("Index out of bounds")

        idx = i + self.size
        self.tree[idx] = value
        while idx > 1:
            idx //= 2
            self.tree[idx] = self.func(self.tree[2 * idx], self.tree[2 * idx + 1])

    def query(self, l, r):
        if l < 0 or r > self.n or l > r:
            raise IndexError("Invalid range")

        if l == r:
            return self.identity

        res = self.identity
        l += self.size
        r += self.size - 1 # Convert [l, r) to inclusive [l, r]

        while l <= r:
            if l % 2 == 1:
                res = self.func(res, self.tree[l])
                l += 1
            if r % 2 == 0:
                res = self.func(res, self.tree[r])
                r -= 1
            l //= 2
            r //= 2
        return res

    def __len__(self):
        return self.n
