def solve(board):
    # Convert input to a mutable 2D list of integers
    grid = []
    for row in board:
        grid_row = []
        for char in row:
            if char == '.':
                grid_row.append(0)
            else:
                grid_row.append(int(char))
        grid.append(grid_row)

    # Check for initial conflicts
    def is_valid_initial(grid):
        for r in range(9):
            for c in range(9):
                if grid[r][c] != 0:
                    val = grid[r][c]
                    # Check row
                    for i in range(9):
                        if i != c and grid[r][i] == val:
                            return False
                    # Check col
                    for i in range(9):
                        if i != r and grid[i][c] == val:
                            return False
                    # Check box
                    start_r, start_c = 3 * (r // 3), 3 * (c // 3)
                    for i in range(start_r, start_r + 3):
                        for j in range(start_c, start_c + 3):
                            if (i != r or j != c) and grid[i][j] == val:
                                return False
        return True

    if not is_valid_initial(grid):
        return None

    def is_safe(r, c, val):
        for i in range(9):
            if grid[r][i] == val or grid[i][c] == val:
                return False
        start_r, start_c = 3 * (r // 3), 3 * (c // 3)
        for i in range(start_r, start_r + 3):
            for j in range(start_c, start_c + 3):
                if grid[i][j] == val:
                    return False
        return True

    def backtrack():
        for r in range(9):
            for c in range(9):
                if grid[r][c] == 0:
                    for val in range(1, 10):
                        if is_safe(r, c, val):
                            grid[r][c] = val
                            if backtrack():
                                return True
                            grid[r][c] = 0
                    return False
        return True

    if backtrack():
        return ["".join(map(str, row)) for row in grid]
    else:
        return None
