class Counter:
    def __init__(self, items=()):
        self.counts = {}
        self._order = []
        for x in items:
            self.add(x)

    def add(self, x, n=1):
        if x not in self.counts:
            self._order.append(x)
        self.counts[x] = self.counts.get(x, 0) + n

    def count(self, x):
        return self.counts.get(x, 0)

    def total(self):
        return sum(self.counts.values())

    def most_common(self, n=None):
        # Sort by count descending, then by original insertion order (stable sort)
        # Python's sort is stable, so we only need to sort by count descending.
        # We use the order in self._order to maintain tie-breaking.
        sorted_items = sorted(self._order, key=lambda x: self.counts[x], reverse=True)
        result = [(x, self.counts[x]) for x in sorted_items]
        return result[:n] if n is not None else result

    def remove(self, x, n=1):
        if x not in self.counts:
            raise KeyError(x)
        self.counts[x] -= n
        if self.counts[x] <= 0:
            del self.counts[x]
            self._order.remove(x)

    def __add__(self, other):
        new_counter = Counter()
        # Add items from self
        for x in self._order:
            new_counter.add(x, self.counts[x])
        # Add items from other
        for x in other.counts:
            new_counter.add(x, other.counts[x])
        return new_counter
