class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None


class BST:
    def __init__(self):
        self.root = None
        self.size = 0

    def insert(self, key):
        """Insert key; duplicates are or ignored. Returns True if the key was added."""
        if self.root is None:
            self.root = Node(key)
            self.size = 1
            return True
        cur = self.root
        while True:
            if key == cur.key:
                return False
            side = "left" if key < cur.key else "right"
            nxt = getattr(cur, side)
            if nxt is None:
                setattr(cur, side, Node(key))
                self.size += 1
                return True
            cur = nxt

    def __contains__(self, key):
        cur = self.root
        while cur:
            if key == cur.key:
                return True
            cur = cur.left if key < cur.key else cur.right
        return False

    def __len__(self):
        return self.size

    def delete(self, key):
        """Delete key; replaces two-child node with in-order successor. Returns True if removed."""
        parent = None
        cur = self.root
        while cur and cur.key != key:
            parent = cur
            cur = cur.left if key < cur.key else cur.right

        if cur is None:
            return False

        # Case: Node has two children
        if cur.left and cur.right:
            # Find in-order successor (smallest in right subtree)
            succ_parent = cur
            succ = cur.right
            while succ.left:
                succ_parent = succ
                succ = succ.left

            # Replace current node's key with successor's key
            cur.key = succ.key
            # Now we need to delete the successor node (which has at most one child)
            # We redirect our pointers to the successor's position
            parent = succ_parent
            cur = succ

        # Case: Node has 0 or 1 child
        # (If it had 2 children, 'cur' and 'parent' were updated to the successor node)
        child = cur.left if cur.left else cur.right

        if parent is None:
            self.root = child
        elif parent.left is cur:
            parent.left = child
        else:
            parent.right = child

        self.size -= 1
        return True

    def inorder(self):
        """Returns a sorted list of keys using iterative approach."""
        res = []
        stack = []
        cur = self.root
        while stack or cur:
            if cur:
                stack.append(cur)
                cur = cur.left
            else:
                cur = stack.pop()
                res.append(cur.key)
                cur = cur.right
        return res

    def height(self):
        """Returns the number of nodes on the longest root-to-leaf path."""
        if not self.root:
            return 0
        max_h = 0
        stack = [(self.root, 1)]
        while stack:
            node, depth = stack.pop()
            if depth > max_h:
                max_h = depth
            if node.right:
                stack.append((node.right, depth + 1))
            if node.left:
                stack.append((node.left, depth + 1))
        return max_h

    def min(self):
        if not self.root:
            raise ValueError("Tree is empty")
        cur = self.root
        while cur.left:
            cur = cur.left
        return cur.key

    def max(self):
        if not self.root:
            raise ValueError("Tree is empty")
        cur = self.root
        while cur.right:
            cur = cur.right
        return cur.key

    def successor(self, key):
        """Returns the smallest key strictly greater than key, or None."""
        succ = None
        cur = self.root
        while cur:
            if cur.key > key:
                succ = cur.key
                cur = cur.left
            else:
                cur = cur.right
        return succ
