from account import Account


class Bank:
    def __init__(self):
        self.accounts = {}

    def open(self, owner, balance=0, overdraft=0):
        if owner in self.accounts:
            raise ValueError("account exists")
        self.accounts[owner] = Account(owner, balance, overdraft)
        return self.accounts[owner]

    def transfer(self, src, dst, amount):
        # Check existence first to ensure atomicity regarding KeyError
        if src not in self.accounts or dst not in self.accounts:
            raise KeyError("one or both accounts do not exist")

        src_acc = self.accounts[src]
        dst_acc = self.accounts[dst]

        # Perform withdrawal first; if it fails (ValueError), nothing has changed
        src_acc.withdraw(amount)

        try:
            # If deposit fails (though unlikely with positive amount), rollback withdrawal
            dst_acc.deposit(amount)
        except Exception as e:
            src_acc.balance += amount
            src_acc.history.append(('withdraw', -amount, src_acc.balance)) # Rollback logic
            raise e

        # Overwrite the history entries for transfers as per requirements
        # Remove the 'withdraw' and 'deposit' entries just created and replace with transfer types
        src_acc.history.pop()
        dst_acc.history.pop()

        src_acc.history.append(('transfer_out', amount, src_acc.balance))
        dst_acc.history.append(('transfer_in', amount, dst_acc.balance))
        return None

    def total(self):
        return sum(acc.balance for acc in self.accounts.values())
