from store import Store


def list_items(store, limit=10, cursor=None):
    if limit < 1:
        raise ValueError("limit must be at least 1")

    rows = store.after(cursor, limit)

    # To determine if there is a next page, we check if there are more items
    # available than what we just fetched.
    next_cursor = None
    if len(rows) == limit:
        # Check if there's at least one more item after the current last item
        # We use count_after on the last item's ID to see if more exist.
        last_item_id = rows[-1]["id"]
        if store.count_after(last_item_id) > 0:
            next_cursor = last_item_id

