class Board:
    LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]

    def __init__(self):
        self.cells = [" "] * 9
        self.turn = "X"
        self.history = []

    def play(self, pos):
        """Place the current player's mark at pos (0-8); IndexError for bad pos, ValueError if taken or game over."""
        if self.over():
            raise ValueError("game over")
        if not 0 <= pos < 9:
            raise IndexError(pos)
        if self.cells[pos] != " ":
            raise ValueError("cell taken")

        self.history.append((pos, self.turn))
        self.cells[pos] = self.turn
        self.turn = "O" if self.turn == "X" else "X"

    def undo(self):
        """Takes back the last move (restoring whose turn it is); IndexError if there are no moves."""
        if not self.history:
            raise IndexError("no moves to undo")
        pos, prev_turn = self.history.pop()
        self.cells[pos] = " "
        self.turn = prev_turn

    def winner(self):
        """Returns 'X', 'O' or None."""
        for line in self.LINES:
            if self.cells[line[0]] != " " and \
               self.cells[line[0]] == self.cells[line[1]] == self.cells[line[2]]:
                return self.cells[line[0]]
        return None

    def is_draw(self):
        """Board full and no winner."""
        return " " not in self.cells and self.winner() is None

    def over(self):
        """Returns True if there is a winner or a draw."""
        return self.winner() is not None or self.is_draw()

    def moves(self):
        """Returns the list of empty positions in ascending order; empty list when the game is over."""
        if self.over():
            return []
        return [i for i, cell in enumerate(self.cells) if cell == " "]

    def __str__(self):
        rows = []
        for i in range(0, 9, 3):
            rows.append("|".join(self.cells[i:i+3]))
        return "\n".join(rows)
