import math

class Money:
    """Amount in integer cents."""

    def __init__(self, cents, currency="USD"):
        self.cents = int(cents)
        self.currency = currency

    def __add__(self, other):
        self._check(other)
        return Money(self.cents + other.cents, self.currency)

    def __sub__(self, other):
        self._check(other)
        return Money(self.cents - other.cents, self.currency)

    def __neg__(self):
        return Money(-self.cents, self.cent_currency_tuple())

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            # Round half away from zero
            new_cents = int(math.floor(self.cents * other + 0.5)) if self.cents >= 0 else int(math.ceil(self.cents * other - 0.5))
            return Money(new_cents, self.currency)
        return NotImplemented

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self.cents == other.cents and self.currency == other.currency

    def __hash__(self):
        return hash((self.cents, self.currency))

    def __lt__(self, other):
        self._check(other)
        return self.cents < other.cents

    def __le__(self, other):
        self._check(other)
        return self.cents <= other.cents

    def _check(self, other):
        if not isinstance(other, Money) or self.currency != other.currency:
            raise ValueError("currency mismatch")

    def cent_currency_tuple(self):
        return self.currency

    def format(self):
        dollars = self.cents / 100.0
        if self.currency == "USD":
            if self.cents < 0:
                return f"-${abs(self.cents) / 100:0.2f}"
            return f"${abs(self.cents) / 100:0.2f}"
        else:
            sign = "-" if self.cents < 0 else ""
            return f"{sign}{abs(self.cents) / 100:0.2f} {self.currency}"

    def allocate(self, ratios):
        if not ratios or any(r < 0 for r in ratios) or sum(ratios) == 0:
            raise ValueError("Invalid ratios")

        is_negative = self.cents < 0
        abs_cents = abs(self.cents)
        total_ratio = sum(ratios)

        parts_cents = []
        remainders = []

        current_sum = 0
        for i, r in enumerate(ratios):
            # floor(total * ratio / sum)
            # To avoid float precision issues with large numbers, use integer math
            # but the requirement implies standard proportional logic.
            # We use the fractional remainder for the redistribution.
            val = (abs_cents * r) // total_ratio
            parts_cents.append(val)

            # Calculate fractional remainder: (abs_cents * r % total_ratio) / total_ratio
            # We can just track the numerator of the remainder: (abs_cents * r) % total_ratio
            remainder_num = (abs_cents * r) % total_ratio
            remainders.append((remainder_num, i))
            current_sum += val

        leftover = abs_cents - current_sum

        # Sort remainders: largest remainder first, then earliest index first
        # Python's sort is stable, so we sort by remainder descending.
        # To handle "ties: earlier part first", we sort by (-remainder, index)
        remainders.sort(key=lambda x: (-x[0], x[1]))

        for i in range(int(leftover)):
            idx = remainders[i][1]
            parts_cents[idx] += 1

        result = []
        for c in parts_cents:
            actual_c = -c if is_negative else c
            result.append(Money(actual_c, self.currency))
        return result

    def __repr__(self):
        return "Money(%d, %r)" % (self.cents, self.currency)
