import heapq


class PriorityQueue:
    """Min-priority queue of (priority, item); ties pop in insertion order.
    Supports updating priorities and lazy removal.
    """

    def __init__(self):
        self._h = []
        self._n = 0
        self._entry_finder = {}  # Maps item to [priority, count, item, removed_flag]
        self._size = 0

    def push(self, item, priority):
        if item in self._entry_finder:
            self.remove(item)

        count = self._n
        # We use a list for the entry so we can mutate the 'removed' flag in-place
        # entry format: [priority, count, item, is_removed]
        entry = [priority, count, item, False]
        self._entry_finder[item] = entry
        heapq.heappush(self._h, entry)
        self._n += 1
        self._size += 1

    def remove(self, item):
        if item not in self._entry_finder:
            raise KeyError(item)
        entry = self._entry_finder.pop(item)
        entry[3] = True  # Mark as removed
        self._size -= 1

    def pop(self):
        while self._h:
            priority, count, item, removed = heapq.heappop(self._h)
            if not removed:
                del self._entry_finder[item]
                self._size -= 1
                return item
        raise IndexError("pop from empty queue")

    def peek(self):
        while self._h:
            priority, count, item, removed = self._h[0]
            if not removed:
                return item
            heapq.heappop(self._h)
        raise IndexError("peek from empty queue")

    def priority(self, item):
        if item not in self._entry_finder:
            raise KeyError(item)
        return self._entry_finder[item][0]

    def __contains__(self, item):
        return item in self._entry_finder

    def __len__(self):
        return self._size
