def parse(text):
    """Parse INI text into {section: {key: value}} (strings). Keys before any section go under ''."""
    out = {}
    cur = ""
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in ";#":
            continue
        if line[0] == "[" and line[-1] == "]":
            cur = line[1:-1].strip()
            out.setdefault(cur, {})
        elif "=" in line:
            k, v = line.split("=", 1)
            out.setdefault(cur, {})[k.strip()] = v.strip()
        else:
            raise ValueError("bad line: " + raw)
    return out

def dump(data):
    """Turn {section: {key: value}} back into INI text."""
    lines = []

    def validate(s):
        if any(c in s for c in "=\n]") or "\n" in s:
            raise ValueError("Invalid character in key or section name")

    # Handle the default section '' first
    if '' in data and data['']:
        for k, v in data[''].items():
            validate(k)
            validate(str(v))
            lines.append(f"{k} = {str(v)}")
        if len(lines) > 0:
            lines.append("")

    # Handle other sections
    for section in data:
        if section == '':
            continue
        validate(section)
        lines.append(f"[{section}]")
        for k, v in data[section].items():
            validate(k)
            validate(str(v))
            lines.append(f"{k} = {str(v)}")
        lines.append("")

    result = "".join(line + "\n" for line in lines)
    # Remove the very last trailing blank line if it exists to match format requirements
    # but the prompt asks for one blank line between blocks and a single trailing newline.
    # The logic above adds a newline after every block. 
    # Let's refine to ensure exact compliance with "one blank line between blocks".

    # Re-implementing dump logic to be precise:
    blocks = []
    # Block 0: empty section
    if '' in data and data['']:
        b = []
        for k, v in data[''].items():
            validate(k); validate(str(v))
            b.append(f"{k} = {str(v)}")
        blocks.append("\n".join(b))

    # Other blocks
    for section in data:
        if section == '': continue
        validate(section)
        b = [f"[{section}]"]
        for k, v in data[section].items():
            validate(k); validate(str(v))
            b.append(f"{k} = {str(v)}")
        blocks.append("\n".join(b))

    if not blocks:
        return ""
    return "\n\n".join(blocks) + "\n"

def get(data, section, key, kind=str, default=None):
    """Returns the converted value, default if missing, with type conversion."""
    try:
        val = data[section][key]
    except KeyError:
        return default

    if kind is bool:
        s = str(val).lower()
        if s in ('1', 'true', 'yes', 'on'):
            return True
        if s in ('0', 'false', 'no', 'off'):
            return False
        raise ValueError(f"Invalid boolean value: {val}")

    try:
        return kind(val)
    except (ValueError, TypeError):
        return default
