def _clean_parts(name):
    parts = name.strip().split()
    return [p.capitalize() for p in parts if p]


def initials(name):
    parts = _clean_parts(name)
    return ".".join(p[0] for p in parts) + ("." if parts else "")


def display(name):
    parts = _clean_parts(name)
    return " ".join(parts)


def sort_key(name):
    parts = _clean_parts(name)
    return (parts[-1] if parts else "", parts[:-1])
