def is_valid(r):
    """Checks if a raw row meets all validation criteria."""
    if not isinstance(r.get("sku"), str) or not r["sku"]:
        return False
    if not isinstance(r.get("qty"), int) or r["qty"] <= 0:
        return False
    if not isinstance(r.get("price"), (int, float)) or r["price"] < 0:
        return False
    return True

def normalize(r):
    """Returns the cleaned dict for a valid row."""
    return {
        "sku": r["sku"].strip().upper(),
        "qty": r["qty"],
        "price": float(r["price"])
    }

def summarize(valid_rows):
    """Returns the aggregated revenue and by_sku totals."""
    revenue = 0.0
    by_sku = {}
    for r in valid_rows:
        line = r["qty"] * r["price"]
        revenue += line
        by_sku[r["sku"]] = round(by_sku.get(r["sku"], 0.0) + line, 2)
    return {"revenue": round(revenue, 2), "by_sku": by_sku}

def process(rows):
    """rows: list of dicts with 'sku', 'qty', 'price'. Returns {'valid': [...], 'rejected': n, 'revenue': float, 'by_sku': {...}}."""
    valid = []
    rejected = 0
    for r in rows:
        if is_valid(r):
            valid.append(normalize(r))
        else:
            rejected += 1

    summary = summarize(valid)
    return {
        "valid": valid,
        "rejected": rejected,
        "revenue": summary["revenue"],
        "by_sku": summary["by_sku"]
    }
