# file: memo.py
from functools import wraps

def memoize(fn):
    @wraps(fn)
    def wrapper(*args):
        if args in wrapper.cache:
            return wrapper.cache[args]
        res = fn(*args)
        wrapper.cache[args] = res
        wrapper.calls += 1
        return res

    wrapper.cache = {}
    wrapper.calls = 0
    return wrapper

@memoize
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

@memoize
def grid_paths(r, c):
    return 1 if r == 0 or c == 0 else grid_paths(r - 1, c) + grid_paths(r, c - 1)
