# file: door.py
TRANSITIONS = {
    ("closed", "open"): "opened",
    ("closed", "lock"): "locked",
    ("opened", "close"): "closed",
    ("locked", "unlock"): "closed",
    ("locked", "kick"): "broken",
}

class Door:
    def __init__(self):
        self.state = "closed"

    def handle(self, event):
        new_state = TRANSITIONS.get((self.state, event))
        if new_state is not None:
            self.state = new_state
            return self.state

        # Check if the state itself is unknown to match the specific error format
        # The original code had a specific branch for 'else' (unknown state)
        # vs 'else' (invalid event in known state).
        known_states = {"closed", "opened", "locked", "broken"}
        if self.state not in known_states:
            raise ValueError("invalid event %s in state %s" % (event, self.state))
        else:
            raise ValueError("invalid event %s in state %s" % (event, self.state))

    def allowed(self):
        if self.state == "broken":
            return []
        events = [
            event for (state, event) in TRANSITIONS.keys() 
            if state == self.state
        ]
        return sorted(events)
