# file: ranges.py
class StepRange:
    def __init__(self, start, stop, step):
        if step <= 0:
            raise ValueError("step must be positive")
        self.start = start
        self.stop = stop
        self.step = step
        self._count = max(0, (stop - start + step - 1) // step) if start < stop else 0

    def __iter__(self):
        x = self.start
        while x < self.stop:
            yield x
            x += self.step

    def __len__(self):
        return self._count

    def __contains__(self, item):
        if not (self.start <= item < self.stop):
            return False
        return (item - self.start) % self.step == 0

    def __getitem__(self, index):
        if isinstance(index, slice):
            # For simplicity in this specific task, we handle integer indices
            raise NotImplementedError("Slices not implemented")

        if index < 0:
            index += self._count

        if 0 <= index < self._count:
            return self.start + index * self.step
        raise IndexError("StepRange index out of range")

    def __repr__(self):
        return f"StepRange({self.start}, {self.stop}, {self.step})"


def step_range(start, stop, step):
    """Return the list start, start+step, ... strictly before stop (step > 0); ValueError if step <= 0."""
    return list(StepRange(start, stop, step))
