# file: times.py
def parse_time(s):
    """Parse '9:05 AM' / '12:30 PM' (12-hour clock) into minutes since midnight."""
    clock, ampm = s.strip().split()
    h, m = clock.split(":")
    h, m = int(h), int(m)
    if not 1 <= h <= 12 or not 0 <= m <= 59:
        raise ValueError("bad time: " + s)

    ampm = ampm.upper()
    if ampm == "PM":
        if h != 12:
            h += 12
    elif ampm == "AM":
        if h == 12:
            h = 0
    else:
        raise ValueError("bad time: " + s)

    return h * 60 + m
