KEYWORDS = ("if", "else", "while", "for", "in", "return")


def lex(src):
    """Split on whitespace into (kind, text): KW for keywords, ID for identifiers, NUM for digit strings."""
    out = []
    for w in src.split():
        if w in KEYWORDS:
            out.append(("KW", w))
        elif w.isdigit():
            out.append(("NUM", w))
        else:
            out.append(("ID", w))
    return out
