class BinOp:
    def __init__(self, op, left, right):
        self.op, self.left, self.right = op, left, right

    def evaluate(self, env):
        a, b = evaluate(self.left, env), evaluate(self.right, env)
        if self.op == "+":
            return a + b
        if self.op == "-":
            return a - b
        if self.op == "*":
            return a * b
        if self.op == "/":
            return a / b
        raise TypeError("unknown node")

    def to_str(self):
        return "(%s %s %s)" % (to_str(self.left), self.op, to_str(self.right))

    def depth(self):
        return 1 + max(depth(self.left), depth(self.right))


def evaluate(node, env):
    try:
        return node.evaluate(env)
    except AttributeError:
        raise TypeError("unknown node")


def to_str(node):
    try:
        return node.to_str()
    except AttributeError:
        raise TypeError("unknown node")


def depth(node):
    try:
        return node.depth()
    except AttributeError:
        raise TypeError("unknown node")
